package com.shopsphere.payment;
import com.shopsphere.common.web.CorrelationIdFilter; import org.springframework.amqp.core.*; import org.springframework.amqp.support.converter.Jackson2JsonMessageConverter; import org.springframework.boot.SpringApplication; import org.springframework.boot.autoconfigure.SpringBootApplication; import org.springframework.context.annotation.Bean;
@SpringBootApplication public class PaymentServiceApplication { public static void main(String[] args){SpringApplication.run(PaymentServiceApplication.class,args);}@Bean CorrelationIdFilter correlationIdFilter(){return new CorrelationIdFilter();}@Bean TopicExchange shopsphereEvents(){return new TopicExchange("shopsphere.events",true,false);}@Bean Queue paymentEvents(){return new Queue("payment.events",true);}@Bean Binding paymentBinding(Queue paymentEvents,TopicExchange shopsphereEvents){return BindingBuilder.bind(paymentEvents).to(shopsphereEvents).with("stock.reserved");}@Bean Jackson2JsonMessageConverter messageConverter(){return new Jackson2JsonMessageConverter();} }
